package com.futurebuild.wealthtree.scanner;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Financial Health Scanner scoring engine: a 1:1 port of the team's score.py
 * (CFPB National Financial Well-Being Survey 2016, 4-dimension weighted regression).
 * Parameters come from model_params.json (generated by fwb_analysis.py; never edit by hand).
 * Output has the same keys and values as score.py / score.js (checked by ScannerParityTest).
 */
public class FinancialHealthScanner {

    private final Map<String, Object> P;

    public FinancialHealthScanner(Map<String, Object> params) {
        this.P = params;
    }

    /** Loads /scanner/model_params.json from the classpath. */
    @SuppressWarnings("unchecked")
    public static FinancialHealthScanner fromClasspath() {
        try (InputStream in = FinancialHealthScanner.class.getResourceAsStream("/scanner/model_params.json")) {
            if (in == null) throw new IllegalStateException("scanner/model_params.json not found on the classpath");
            return new FinancialHealthScanner((Map<String, Object>) MiniJson.parse(new String(in.readAllBytes(), StandardCharsets.UTF_8)));
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }

    public Map<String, Object> params() { return P; }

    // ------------------------------------------------------------------ helpers
    private static Double num(Object v) {
        if (v == null) return null;
        if (v instanceof Number n) { double x = n.doubleValue(); return Double.isNaN(x) ? null : x; }
        if (v instanceof Boolean b) return b ? 1.0 : 0.0;
        String s = v.toString().trim();
        if (s.isEmpty()) return null;
        try { double x = Double.parseDouble(s); return Double.isNaN(x) ? null : x; } catch (NumberFormatException e) { return null; }
    }

    private static int roundHalfUp(double x) { return (int) Math.floor(x + 0.5); }

    @SuppressWarnings("unchecked")
    private Map<String, Object> map(Object o) { return (Map<String, Object>) o; }

    @SuppressWarnings("unchecked")
    private List<Object> list(Object o) { return (List<Object>) o; }

    private static boolean contains(List<Object> l, double x) {
        for (Object o : l) if (((Number) o).doubleValue() == x) return true;
        return false;
    }

    private static String pyRepr(Object raw) {
        if (raw instanceof String s) return "'" + s + "'";
        if (raw instanceof Double d && d == Math.rint(d) && !Double.isInfinite(d)) return String.valueOf(d.longValue());
        return String.valueOf(raw);
    }

    // ------------------------------------------------------------------ scoring (same order of operations as score.py)
    /** Original survey code -> 0..1 (reverse-coded where specified), or null if missing/invalid. */
    public Double itemValue(String name, Object raw, List<String> warnings) {
        Map<String, Object> spec = map(map(P.get("items")).get(name));
        Double x = num(raw);
        if (x == null) return null;
        Object recObj = spec.get("recode");
        if (recObj != null && x == Math.rint(x)) {
            Object r = map(recObj).get(String.valueOf((long) x.doubleValue()));
            if (r != null) x = ((Number) r).doubleValue();
        }
        if (!contains(list(spec.get("valid")), x)) {
            if (warnings != null && !contains(list(spec.get("missing_codes")), x))
                warnings.add(name + ": code " + pyRepr(raw) + " is not a valid response code; treated as missing");
            return null;
        }
        double lo = ((Number) spec.get("lo")).doubleValue(), hi = ((Number) spec.get("hi")).doubleValue();
        double r = (x - lo) / (hi - lo);
        return Boolean.TRUE.equals(spec.get("reverse")) ? 1 - r : r;
    }

    private Double composite(String name, Map<String, Object> answers, List<String> warnings) {
        Map<String, Object> c = map(map(P.get("composites")).get(name));
        List<Double> vals = new ArrayList<>();
        for (Object i : list(c.get("items"))) {
            Double v = itemValue((String) i, answers.get(i), warnings);
            if (v != null) vals.add(v);
        }
        if (vals.size() < ((Number) c.get("min_items")).intValue()) return null;
        double s = 0;
        for (double v : vals) s += v;
        return s / vals.size();
    }

    /** 0..100 mean of the dimension's rescaled items; null unless at least half its items are valid. */
    public Double dimensionScore(String dim, Map<String, Object> answers, List<String> warnings) {
        List<Object> items = list(map(P.get("dimensions")).get(dim));
        Map<String, Object> comps = map(P.get("composites"));
        List<Double> vals = new ArrayList<>();
        for (Object o : items) {
            String i = (String) o;
            Double v = comps.containsKey(i) ? composite(i, answers, warnings) : itemValue(i, answers.get(i), warnings);
            if (v != null) vals.add(v);
        }
        if (vals.size() < (int) Math.ceil(items.size() / 2.0)) return null;
        double s = 0;
        for (double v : vals) s += v;
        return 100 * s / vals.size();
    }

    /** Uses agecat (CFPB code 1-8) if given, otherwise age in years. */
    public String ageBand(Map<String, Object> answers) {
        Double ac = num(answers.get("agecat")), age = num(answers.get("age"));
        for (Object o : list(P.get("age_bands"))) {
            Map<String, Object> b = map(o);
            if (ac != null && contains(list(b.get("agecat")), ac)) return (String) b.get("band");
            List<Object> r = list(b.get("age"));
            if (ac == null && age != null && ((Number) r.get(0)).doubleValue() <= age && age <= ((Number) r.get(1)).doubleValue())
                return (String) b.get("band");
        }
        return null;
    }

    /** Weighted mid-rank percentile (0-100) of x within the age band's PUF distribution of metric. */
    public Double percentile(String metric, String band, Double x) {
        if (band == null || x == null) return null;
        List<Object> p = list(map(map(P.get("percentile_tables")).get(metric)).get(band));
        int k = Math.min(100, Math.max(0, roundHalfUp(x)));
        double below = 0;
        for (int j = 0; j < k; j++) below += ((Number) p.get(j)).doubleValue();
        return 100 * (below + 0.5 * ((Number) p.get(k)).doubleValue());
    }

    public Map<String, Object> score(Map<String, Object> answers) {
        List<String> warnings = new ArrayList<>();
        String band = ageBand(answers);
        if (band == null) warnings.add("age missing or under 18: percentiles not available");
        List<Object> scored = list(P.get("scored_dimensions"));
        Map<String, Double> dims = new LinkedHashMap<>();
        for (Object d : scored) dims.put((String) d, dimensionScore((String) d, answers, warnings));
        List<String> missing = new ArrayList<>();
        dims.forEach((d, v) -> { if (v == null) missing.add(d); });
        Double pred = null;
        Boolean clipped = null;
        if (missing.isEmpty()) {
            Map<String, Object> coef = map(P.get("coef"));
            double sum = 0;
            for (Map.Entry<String, Double> e : dims.entrySet()) sum += ((Number) coef.get(e.getKey())).doubleValue() * e.getValue();
            double raw = ((Number) P.get("intercept")).doubleValue() + sum;
            List<Object> clip = list(P.get("score_clip"));
            pred = Math.min(((Number) clip.get(1)).doubleValue(), Math.max(((Number) clip.get(0)).doubleValue(), raw));
            clipped = pred != raw;
        }
        if (pred != null && itemValue("SAVINGSRANGES", answers.get("SAVINGSRANGES"), null) == null)
            warnings.add("SAVINGSRANGES not answered: reserves rests on ABSORBSHOCK only; predicted score is less reliable (R2 "
                    + fmtR2(P.get("R2_when_SAVINGSRANGES_missing")) + " vs " + fmtR2(P.get("R2")) + " in the PUF)");
        Double habits = dimensionScore("habits", answers, warnings);

        Map<String, Object> dimOut = new LinkedHashMap<>();
        for (Map.Entry<String, Double> e : dims.entrySet()) {
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("score", e.getValue());
            m.put("percentile", percentile(e.getKey(), band, e.getValue()));
            dimOut.put(e.getKey(), m);
        }
        Map<String, Object> hab = new LinkedHashMap<>();
        hab.put("score", habits);
        hab.put("percentile", percentile("habits", band, habits));

        Map<String, Object> out = new LinkedHashMap<>();
        out.put("age_band", band);
        out.put("dimensions", dimOut);
        out.put("predicted_score", pred);
        out.put("predicted_score_clipped", clipped);
        out.put("predicted_score_percentile", percentile("predicted_score", band, pred));
        out.put("missing_dimensions", missing);
        out.put("habits_display_only", hab);
        out.put("warnings", warnings);
        return out;
    }

    private static String fmtR2(Object o) {
        double d = ((Number) o).doubleValue();
        return d == Math.rint(d) ? String.valueOf((long) d) : String.valueOf(d);
    }

    /** Predicted point gain from changing answers, holding everything else fixed (association, not causation). */
    @SuppressWarnings("unchecked")
    public Map<String, Object> whatIf(Map<String, Object> baseline, Map<String, Object> change) {
        Map<String, Object> merged = new LinkedHashMap<>(baseline);
        merged.putAll(change);
        Map<String, Object> before = score(baseline), after = score(merged);
        Double b = (Double) before.get("predicted_score"), a = (Double) after.get("predicted_score");
        Map<String, Object> dc = new LinkedHashMap<>();
        for (Object d : list(P.get("scored_dimensions"))) {
            Double x = (Double) ((Map<String, Object>) ((Map<String, Object>) before.get("dimensions")).get(d)).get("score");
            Double y = (Double) ((Map<String, Object>) ((Map<String, Object>) after.get("dimensions")).get(d)).get("score");
            dc.put((String) d, x == null || y == null ? null : y - x);
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("change", change);
        out.put("baseline_score", b);
        out.put("new_score", a);
        out.put("predicted_gain", b == null || a == null ? null : a - b);
        out.put("dimension_changes", dc);
        out.put("baseline_percentile", before.get("predicted_score_percentile"));
        out.put("new_percentile", after.get("predicted_score_percentile"));
        return out;
    }
}
